  @override
  List<String> get customConstraints => const [
    'CHECK((status IN (\'COMPLETED\', \'PARTIAL\') AND completed_at IS NOT NULL)OR(status NOT IN (\'COMPLETED\', \'PARTIAL\') AND completed_at IS NULL))',
