    'CHECK(scheduled_at IS NULL OR expires_at IS NULL OR scheduled_at <= expires_at)',
    'CHECK(available_from IS NULL OR expires_at IS NULL OR available_from <= expires_at)',
  ];
  @override
  bool get dontWriteConstraints => true;
