    return (StringBuffer('Project(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('description: $description, ')
          ..write('iconKey: $iconKey, ')
          ..write('kind: $kind, ')
          ..write('status: $status, ')
          ..write('missionId: $missionId, ')
          ..write('resultItemId: $resultItemId, ')
          ..write('completedAt: $completedAt, ')
